def btn(text='Start a project',url='/contact/',secondary=False):return f'<a class="button {"secondary" if secondary else ""}" href="{url}">{text}<span aria-hidden="true">↗</span></a>'
def label(t):return f'<p class="eyebrow">{t}</p>'
def heading(k,h,p=''):return f'<section class="pagehero wrap">{label(k)}<h1>{h}</h1>'+ (f'<p class="intro">{p}</p>' if p else '')+'</section>'
def cta():return '<section class="cta wrap">'+label('YOUR NEXT CHAPTER')+'<h2>Big ambitions?<br>Let’s <em>ignite them.</em></h2>'+btn()+'</section>'
def cards():return '<div class="service-grid">'+''.join(f'<a class="service-card" href="/services/{s[0]}/"><div class="card-top"><span class="mono">/ {s[1]}</span><span>↗</span></div><h3>{s[2]}</h3><h4>{s[3]}</h4><p>{s[8]}</p><div class="card-bottom">Explore {"web design" if s[0]=="websites" else s[0]} <span>→</span></div></a>' for s in services)+'</div>'
faqs=[('What does a typical project include?','We agree the scope around your goals. A website project can include structure, design, development, content guidance, launch checks and handover. Automation and content can be added where they solve a clear problem.'),('How long does a website take?','Timing depends on the pages, integrations and content readiness. We agree milestones before work begins and flag anything that could affect launch.'),('Can you work with our existing tools?','We review your current tools first, then recommend the smallest useful change. Integrations are confirmed during discovery.'),('Do you support the site after launch?','Yes. Ongoing support and maintenance can cover updates, new features and performance improvements. We agree the level of support with you.'),('What happens after I enquire?','We review your goals and arrange a first conversation. Then we outline the scope, timeline and costs so you can decide whether to move forward.')]
def faq():return '<section class="wrap faq"><div>'+label('A LITTLE CLARITY')+'<h2>Good questions.<br>Straight answers.</h2></div><div>'+''.join(f'<details><summary>{q}<span>+</span></summary><p>{a}</p></details>' for q,a in faqs)+'</div></section>'
articles=[('website-warning-signs','Build','Five signs your website has outgrown your business.','A useful redesign starts with the friction your customers feel.', [('Your offer has moved on','Open your homepage and compare it with the work you want to win now. If the headline describes yesterday’s business, fix the message before choosing a new layout.'),('The next step is hard to find','Ask someone unfamiliar with your business to find how to enquire on a phone. Watch where they hesitate. A clear action and a shorter route can matter more than another animation.'),('Your strongest work is missing','Replace outdated examples with relevant work you have permission to share. Explain the problem and what you delivered. Only attach results that you can substantiate.'),('Small updates take too much effort','List the changes you make regularly: services, work, team details or opening hours. Your publishing setup should let the right person make those edits confidently.'),('Start with one page','Choose the page closest to your main enquiry path. Rewrite its promise, simplify the next step and review the response before committing to a complete rebuild.')]),('automate-first','Automate','What to automate first when leads go quiet.','Start with the handoffs that are easiest to miss.', [('Map the current journey','Follow an enquiry from its first form submission to the first real conversation. Write down who owns each step and which tools hold the information.'),('Give each lead an owner','Before adding messages, define who responds and what the next action is. A pipeline only helps when someone keeps it accurate.'),('Make acknowledgement useful','A simple confirmation can explain what happens next. Keep marketing permissions separate and avoid promising a response time the team cannot meet.'),('Test the exceptions','Try an invalid email, a duplicate enquiry and a cancelled booking. Make failures visible to a person rather than leaving a lead stuck silently.'),('Keep real conversations personal','Use automation for routing and reminders. Let your team handle questions, judgement and the conversations that build trust.')]),('content-system','Dominate','Build a content system you can actually maintain.','Consistency starts with a plan that fits your team.', [('Choose a repeatable rhythm','Decide how much useful content your team can make in an ordinary week. Start there rather than setting a schedule that only works when nothing else is happening.'),('Give every post a job','Use four pillars: point of view, proof, personality and product. A post should teach, demonstrate, introduce or explain something your audience cares about.'),('Capture while you work','Keep a shared list of customer questions, decisions and lessons. Get permission before showing clients or sharing their information.'),('Batch the production','Turn a single useful topic into a short video, a carousel or a written post. Adapt the format instead of repeating the same asset everywhere.'),('Review what starts conversations','Look beyond reach. Record the questions and enquiries content creates, then use those signals to choose the next topics.')])]
def articlecards():return '<div class="insight-grid">'+''.join(f'<a class="insight-card" href="/insights/{slug}/">{label(cat+" / FIELD NOTES")}<h3>{title}</h3><p>{desc}</p><span class="read">Read the note ↗</span></a>' for slug,cat,title,desc,sections in articles)+'</div>'
